import{c as t,Q as a,j as o,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/settings.md","filePath":"configuration/settings.md","lastUpdated":null}'),s={name:"configuration/settings.md"};function n(i,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>All user-controlled configuration — provider, data, and server account.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><ul><li><strong>Agent</strong> — provider choice (Ollama / OpenAI-compatible / Anthropic), models, and the data-flow explanation shown before you save. Keys are per-user in <code>data.sqlcipher</code>.</li><li><strong>Data &amp; backups</strong> — create encrypted per-user snapshots under <code>users/&lt;uuid&gt;/backups/</code> and restore them. For disaster recovery, also back up the whole <code>/data</code> volume (includes <code>users.db</code> + <code>session.key</code>).</li><li><strong>Exports</strong> — CSV export of transactions/reports; streamed from the server, no third party.</li><li><strong>Account</strong> — rename self, manage users (admin only), change password, recovery key rotation, and “sign out other devices” (revokes persisted sessions).</li><li><strong>Appearance</strong> — theme (system / light / dark) and density; persisted to <code>localStorage</code>.</li></ul><h2 id="provider-keys" tabindex="-1">Provider keys <a class="header-anchor" href="#provider-keys" aria-label="Permalink to &quot;Provider keys&quot;">​</a></h2><p>Changing a provider key re-wraps nothing and touches no other user — the key is a row in your encrypted database. Removing the key disables Copilot + auto-categorization immediately; deterministic heuristics remain.</p><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p>The first account is the administrator. At <strong>Settings → Account → Manage users</strong> it can create and delete non-admin users. Creation issues a one-time recovery key; deletion removes <code>users/&lt;uuid&gt;/</code> and revokes that user’s sessions.</p><p>See also: <a href="/FinSight/configuration/ollama">Ollama</a>, <a href="/FinSight/configuration/openai-compatible">OpenAI-Compatible</a>, <a href="/FinSight/configuration/anthropic">Anthropic</a>.</p>',9)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
